@AI {
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": "/results.csv"
  }
  "transform": [
    {
      "aggregate": [
        {
          "op": "count",
          "as": "count"
        }
      ],
      "groupby": ["country"]
    },
    {
      "window": [
        {
          "op": "rank",
          "as": "rank"
        }
      ],
      "sort": [
        {
          "field": "count",
          "order": "descending"
        }
      ]
    },
    {
      "filter": "datum.rank <= 10"
    }
  ],
  "mark": "bar",
  "encoding": {
    "y": {"field": "count", "type": "quantitative"},
    "x": {"field": "country", "type": "ordinal", "sort": "-y"}
  }
